function flattenObj(obj, prefix = "") {
  return Object.entries(obj).reduce((acc, [key, val]) => {
    const newKey = prefix ? `${prefix}.${key}` : key
    if (typeof val === "object" && val !== null && !Array.isArray(val)) {
      Object.assign(acc, flattenObj(val, newKey))
    } else {
      acc[newKey] = val
    }
    return acc
  }, {})
}
